namespace Verce.Modules.Commerce;

[JsonConverter(typeof(JsonStringEnumConverter<MarketplaceListingSyncKind>))]
public enum MarketplaceListingSyncKind { FULL, FAILED_ONLY }
[JsonConverter(typeof(JsonStringEnumConverter<MarketplaceListingSyncStatus>))]
public enum MarketplaceListingSyncStatus { QUEUED, RUNNING, SUCCEEDED, PARTIAL, FAILED }
[JsonConverter(typeof(JsonStringEnumConverter<MarketplaceListingSyncPhase>))]
public enum MarketplaceListingSyncPhase { ENUMERATING, RECONCILING_MISSING, DETAILING }
[JsonConverter(typeof(JsonStringEnumConverter<MarketplaceListingSyncItemOrigin>))]
public enum MarketplaceListingSyncItemOrigin { ENUMERATED, KNOWN_NOT_ENUMERATED, RETRY_TARGET }
[JsonConverter(typeof(JsonStringEnumConverter<MarketplaceListingSyncItemOutcome>))]
public enum MarketplaceListingSyncItemOutcome { PENDING, FOUND, NOT_FOUND, ACCESS_DENIED, SELLER_MISMATCH, TRANSIENT_ERROR, PERMANENT_ERROR }
[JsonConverter(typeof(JsonStringEnumConverter<MarketplaceListingLinkageSource>))]
public enum MarketplaceListingLinkageSource { MANUAL, DETERMINISTIC_SKU }
[JsonConverter(typeof(JsonStringEnumConverter<MarketplaceAccountSkuMappingInvalidatedReason>))]
public enum MarketplaceAccountSkuMappingInvalidatedReason { OPERATOR_DEACTIVATED, REPLACED_BY_NEW_MAPPING }

public sealed class MarketplaceListingSyncRun : TechnicalEntity, ITechnicalTable
{
    private MarketplaceListingSyncRun() { }
    public MarketplaceListingSyncRun(Guid accountId, string providerCode, Guid requestedByUserId, DateTimeOffset requestedAt, int maxAttempts = 3)
    { if(accountId==Guid.Empty||requestedByUserId==Guid.Empty) throw new ArgumentException("LISTING_SYNC_REFERENCE_REQUIRED"); if(maxAttempts is <1 or >10) throw new ArgumentException("LISTING_SYNC_MAX_ATTEMPTS_INVALID"); MarketplaceAccountId=accountId; ProviderCode=MarketplaceProvider.RequiredCode(providerCode); RequestedByUserId=requestedByUserId; RequestedAt=UpdatedAt=requestedAt; MaxAttempts=maxAttempts; Kind=MarketplaceListingSyncKind.FULL; Status=MarketplaceListingSyncStatus.QUEUED; RootRunId=Id; }
    public Guid MarketplaceAccountId {get;private set;} public string ProviderCode {get;private set;}=string.Empty; public MarketplaceListingSyncKind Kind {get;private set;} public MarketplaceListingSyncStatus Status {get;private set;} public MarketplaceListingSyncPhase? Phase {get;private set;} public Guid RootRunId {get;private set;} public Guid? RetryOfRunId {get;private set;} public Guid RequestedByUserId {get;private set;} public DateTimeOffset RequestedAt {get;private set;} public DateTimeOffset UpdatedAt {get;private set;} public DateTimeOffset? StartedAt {get;private set;} public DateTimeOffset? FinishedAt {get;private set;} public DateTimeOffset? HeartbeatAt {get;private set;} public DateTimeOffset? LeaseUntil {get;private set;} public Guid? LeaseToken {get;private set;} public int AttemptCount {get;private set;} public int MaxAttempts {get;private set;} public bool EnumerationCompleted {get;private set;} public string? SafeResultCode {get;private set;} public string? LastFailureClassification {get;private set;} public string? ProviderErrorCode {get;private set;} public DateTimeOffset? RetryAfterUntil {get;private set;} public Guid? ConfirmedOperationIdAtStart {get;private set;} public long Version {get;private set;}=1;
    internal static MarketplaceListingSyncRun CreateRetry(MarketplaceListingSyncRun source, Guid actorId, DateTimeOffset now, int maxAttempts = 3)
    { if(!source.IsTerminal) throw new InvalidOperationException("LISTING_SYNC_RETRY_SOURCE_NOT_TERMINAL"); var retry=new MarketplaceListingSyncRun(source.MarketplaceAccountId,source.ProviderCode,actorId,now,maxAttempts); retry.Kind=MarketplaceListingSyncKind.FAILED_ONLY; retry.RootRunId=source.RootRunId; retry.RetryOfRunId=source.Id; retry.EnumerationCompleted=false; return retry; }
    internal bool IsTerminal => Status is MarketplaceListingSyncStatus.SUCCEEDED or MarketplaceListingSyncStatus.PARTIAL or MarketplaceListingSyncStatus.FAILED;
    internal void MarkEnumerationCompleted(DateTimeOffset now){if(Kind!=MarketplaceListingSyncKind.FULL||Status!=MarketplaceListingSyncStatus.RUNNING)throw new InvalidOperationException("LISTING_SYNC_ENUMERATION_INVALID_STATE");EnumerationCompleted=true;UpdatedAt=now;Version++;}
    internal void SetPhase(MarketplaceListingSyncPhase phase,DateTimeOffset now){if(IsTerminal||Status!=MarketplaceListingSyncStatus.RUNNING)throw new InvalidOperationException("LISTING_SYNC_PHASE_INVALID_STATE");Phase=phase;UpdatedAt=now;Version++;}
    internal void Terminalize(MarketplaceListingSyncStatus status,string safeResultCode,DateTimeOffset now)
    {if(!IsTerminal && status is MarketplaceListingSyncStatus.SUCCEEDED or MarketplaceListingSyncStatus.PARTIAL or MarketplaceListingSyncStatus.FAILED){if(Kind==MarketplaceListingSyncKind.FULL && status is MarketplaceListingSyncStatus.SUCCEEDED or MarketplaceListingSyncStatus.PARTIAL && !EnumerationCompleted)throw new InvalidOperationException("LISTING_SYNC_ENUMERATION_INCOMPLETE");Status=status;SafeResultCode=MarketplaceListingSyncKernel.RequiredSafeCode(safeResultCode);FinishedAt=now;LeaseToken=null;LeaseUntil=null;HeartbeatAt=null;Phase=null;UpdatedAt=now;Version++;return;}throw new InvalidOperationException("LISTING_SYNC_TERMINAL_TRANSITION_INVALID");}
}
public sealed class MarketplaceListingSyncRunItem : TechnicalEntity, ITechnicalTable
{
    private MarketplaceListingSyncRunItem() { }
    public MarketplaceListingSyncRunItem(Guid runId,string externalListingId,MarketplaceListingSyncItemOrigin origin,DateTimeOffset now){if(runId==Guid.Empty)throw new ArgumentException("LISTING_SYNC_RUN_REQUIRED");SyncRunId=runId;ExternalListingId=MarketplaceProvider.Required(externalListingId,1,200);Origin=origin;Outcome=MarketplaceListingSyncItemOutcome.PENDING;CreatedAt=UpdatedAt=now;}
    public Guid SyncRunId {get;private set;} public string ExternalListingId {get;private set;}=string.Empty; public MarketplaceListingSyncItemOrigin Origin {get;private set;} public MarketplaceListingSyncItemOutcome Outcome {get;private set;} public Guid? MarketplaceListingId {get;private set;} public string? SafeErrorCode {get;private set;} public string? ProviderErrorCode {get;private set;} public int AttemptCount {get;private set;} public bool ListingCreated {get;private set;} public bool ObservationAppended {get;private set;} public DateTimeOffset CreatedAt {get;private set;} public DateTimeOffset UpdatedAt {get;private set;} public DateTimeOffset? CompletedAt {get;private set;}
    /// <summary>Called only by the B2 execution transaction after B1's lease guard has become
    /// the first statement. The aggregate still rejects any non-pending or malformed transition.</summary>
    public void Record(MarketplaceListingSyncItemOutcome outcome,string? safeErrorCode,Guid? marketplaceListingId,bool listingCreated,bool observationAppended,DateTimeOffset now)
    {if(Outcome!=MarketplaceListingSyncItemOutcome.PENDING)throw new InvalidOperationException("LISTING_SYNC_ITEM_ALREADY_TERMINAL");if(outcome==MarketplaceListingSyncItemOutcome.PENDING)throw new ArgumentException("LISTING_SYNC_ITEM_OUTCOME_INVALID");if(outcome==MarketplaceListingSyncItemOutcome.FOUND){if(marketplaceListingId is null||marketplaceListingId==Guid.Empty||safeErrorCode is not null)throw new ArgumentException("LISTING_SYNC_ITEM_FOUND_INVALID");MarketplaceListingId=marketplaceListingId;ListingCreated=listingCreated;ObservationAppended=observationAppended;SafeErrorCode=null;}else{if(string.IsNullOrWhiteSpace(safeErrorCode))throw new ArgumentException("LISTING_SYNC_ITEM_SAFE_CODE_REQUIRED");SafeErrorCode=MarketplaceListingSyncKernel.RequiredSafeCode(safeErrorCode);MarketplaceListingId=null;}Outcome=outcome;CompletedAt=UpdatedAt=now;AttemptCount++;}
}
[Auditable]
public sealed class MarketplaceAccountSkuMapping : AggregateRoot
{
    private MarketplaceAccountSkuMapping() { }
    public MarketplaceAccountSkuMapping(Guid accountId,string externalSku,Guid productId,Guid actorId,DateTimeOffset now){if(accountId==Guid.Empty||productId==Guid.Empty||actorId==Guid.Empty)throw new ArgumentException("SKU_MAPPING_REFERENCE_REQUIRED");MarketplaceAccountId=accountId;ExternalSku=MarketplaceSkuNormalizer.Normalize(externalSku);ProductId=productId;ConfirmedByUserId=actorId;ConfirmedAt=now;Active=true;}
    public Guid MarketplaceAccountId {get;private set;} public string ExternalSku {get;private set;}=string.Empty; public Guid ProductId {get;private set;} public bool Active {get;private set;} public Guid ConfirmedByUserId {get;private set;} public DateTimeOffset ConfirmedAt {get;private set;} public DateTimeOffset? InvalidatedAt {get;private set;} public Guid? InvalidatedByUserId {get;private set;} public MarketplaceAccountSkuMappingInvalidatedReason? InvalidatedReason {get;private set;}
    /// <summary>ADR-0025 §D.3: explicit operator deactivation. A mapping is never reactivated (confirm a new one instead) and the transition never touches a listing.</summary>
    public void Deactivate(Guid actorId, DateTimeOffset now) => Invalidate(MarketplaceAccountSkuMappingInvalidatedReason.OPERATOR_DEACTIVATED, actorId, now);
    /// <summary>ADR-0025 §D.3: the previous ACTIVE mapping when a confirmation names it for replacement; the caller creates the new mapping in the same unit of work.</summary>
    public void Replace(Guid actorId, DateTimeOffset now) => Invalidate(MarketplaceAccountSkuMappingInvalidatedReason.REPLACED_BY_NEW_MAPPING, actorId, now);
    private void Invalidate(MarketplaceAccountSkuMappingInvalidatedReason reason, Guid actorId, DateTimeOffset now)
    {
        if (actorId == Guid.Empty) throw new ArgumentException("SKU_MAPPING_REFERENCE_REQUIRED", nameof(actorId));
        if (!Active) throw new InvalidOperationException("SKU_MAPPING_NOT_ACTIVE");
        Active = false; InvalidatedAt = now; InvalidatedByUserId = actorId; InvalidatedReason = reason;
    }
}

/// <summary>Canonical internal SKU identity for deterministic marketplace mapping lookup and storage.</summary>
public static class MarketplaceSkuNormalizer
{
    public static string Normalize(string value)
    {
        if (value is null) throw new ArgumentNullException(nameof(value));
        var normalized = string.Concat(value.Normalize(NormalizationForm.FormC).Trim().Where(c => !char.IsControl(c)));
        if (normalized.Length is < 1 or > 200) throw new ArgumentException("SKU_MAPPING_SKU_INVALID", nameof(value));
        return normalized;
    }
}

