HasMaxLength(64);b.Property(x=>x.MaxAttempts).HasDefaultValue(3);b.Property(x=>x.EnumerationCompleted).HasDefaultValue(false);b.Property(x=>x.Version).IsConcurrencyToken();b.HasIndex(x=>x.MarketplaceAccountId).IsUnique().HasFilter("status IN ('QUEUED','RUNNING')");b.HasIndex(x=>new{x.Status,x.RequestedAt}).HasFilter("status IN ('QUEUED','RUNNING')");b.HasIndex(x=>new{x.Status,x.LeaseUntil}).HasFilter("status = 'RUNNING'");b.HasIndex(x=>new{x.MarketplaceAccountId,x.Kind,x.RequestedAt}).IsDescending(false,false,true);b.HasIndex(x=>new{x.RootRunId,x.RequestedAt});b.HasIndex(x=>x.RetryOfRunId);b.HasOne<MarketplaceAccount>().WithMany().HasForeignKey(x=>x.MarketplaceAccountId).OnDelete(DeleteBehavior.Restrict);b.HasOne<MarketplaceProvider>().WithMany().HasForeignKey(x=>x.ProviderCode).OnDelete(DeleteBehavior.Restrict);b.HasOne<MarketplaceListingSyncRun>().WithMany().HasForeignKey(x=>x.RootRunId).HasConstraintName("fk_marketplace_listing_sync_run_root_run").OnDelete(DeleteBehavior.Restrict);b.HasOne<MarketplaceListingSyncRun>().WithMany().HasForeignKey(x=>x.RetryOfRunId).HasConstraintName("fk_marketplace_listing_sync_run_retry_of_run").OnDelete(DeleteBehavior.Restrict);}}
public sealed class MarketplaceListingSyncRunItemConfiguration : IEntityTypeConfiguration<MarketplaceListingSyncRunItem>{public void Configure(EntityTypeBuilder<MarketplaceListingSyncRunItem>b){b.ToTable("marketplace_listing_sync_run_item","commerce",t=>{t.HasCheckConstraint("ck_marketplace_listing_sync_run_item_origin","origin IN ('ENUMERATED','KNOWN_NOT_ENUMERATED','RETRY_TARGET')");t.HasCheckConstraint("ck_marketplace_listing_sync_run_item_outcome","outcome IN ('PENDING','FOUND','NOT_FOUND','ACCESS_DENIED','SELLER_MISMATCH','TRANSIENT_ERROR','PERMANENT_ERROR')");t.HasCheckConstraint("ck_marketplace_listing_sync_run_item_attempts","attempt_count >= 0");t.HasCheckConstraint("ck_marketplace_listing_sync_run_item_completion","(outcome = 'PENDING') = (completed_at IS NULL)");t.HasCheckConstraint("ck_marketplace_listing_sync_run_item_result","(outcome = 'FOUND' AND marketplace_listing_id IS NOT NULL AND safe_error_code IS NULL) OR (outcome = 'PENDING') OR (outcome <> 'FOUND' AND safe_error_code IS NOT NULL)");});b.HasKey(x=>x.Id);b.Property(x=>x.Id).ValueGeneratedNever();b.Property(x=>x.ExternalListingId).HasMaxLength(200);b.Property(x=>x.Origin).HasConversion<string>().HasMaxLength(24);b.Property(x=>x.Outcome).HasConversion<string>().HasMaxLength(24);b.Property(x=>x.SafeErrorCode).HasMaxLength(64);b.Property(x=>x.ProviderErrorCode).HasMaxLength(64);b.Property(x=>x.ListingCreated).HasDefaultValue(false);b.Property(x=>x.ObservationAppended).HasDefaultValue(false);b.HasIndex(x=>new{x.SyncRunId,x.ExternalListingId}).IsUnique();b.HasIndex(x=>new{x.SyncRunId,x.Outcome,x.Origin,x.ExternalListingId});b.HasIndex(x=>x.MarketplaceListingId);b.HasOne<MarketplaceListingSyncRun>().WithMany().HasForeignKey(x=>x.SyncRunId).OnDelete(DeleteBehavior.Restrict);b.HasOne<MarketplaceListing>().WithMany().HasForeignKey(x=>x.MarketplaceListingId).OnDelete(DeleteBehavior.Restrict);}}
